import { useEffect } from 'react';
import { X } from 'lucide-react';
import Rich from './Rich';

const lockScroll = (isOpen) => {
  if (isOpen) {
    const sw = window.innerWidth - document.documentElement.clientWidth;
    document.documentElement.style.overflow = 'hidden';
    if (sw > 0) {
      document.documentElement.style.paddingRight = `${sw}px`;
      const h = document.querySelector('header');
      if (h) h.style.paddingRight = `${sw}px`;
    }
  } else {
    document.documentElement.style.overflow = '';
    document.documentElement.style.paddingRight = '';
    const h = document.querySelector('header');
    if (h) h.style.paddingRight = '';
  }
};

export default function PrivacyPopup({ isOpen, onClose, openContactPopup, t }) {
  useEffect(() => { lockScroll(isOpen); return () => lockScroll(false); }, [isOpen]);
  if (!isOpen) return null;
  const sections = ['browsing', 'cameraMic', 'downloads', 'mouseKeyboard', 'adBlocker', 'localStorage', 'appleData', 'anonymousUsage', 'appStore', 'thirdParty', 'children', 'changes'];
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70" onClick={onClose}>
      <div className="legal-modal backdrop-blur-xl max-w-2xl w-full max-h-[85vh] overflow-hidden" onClick={e => e.stopPropagation()}>
        <div className="legal-modal-header mx-4 my-4 p-4 flex items-center justify-between sticky top-0 z-10">
          <h3 className="text-xl font-bold text-white">{t('privacyPolicy.title')}</h3>
          <button onClick={onClose} className="text-white hover:bg-white/20 rounded-full p-2 transition-all duration-200 hover:scale-105"><X size={24} /></button>
        </div>
        <div className="overflow-y-auto max-h-[calc(85vh-8rem)] px-6 pb-6">
          <div className="prose prose-sm sm:prose dark:prose-invert max-w-none pt-6">
            <p className="text-slate-600 dark:text-slate-400 mb-4"><strong>{t('privacyPolicy.lastUpdatedLabel')}</strong> {t('privacyPolicy.lastUpdatedDate')}</p>

            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mt-6 mb-3">{t('privacyPolicy.intro.heading')}</h3>
            <p className="text-slate-700 dark:text-slate-300 mb-4"><Rich text={t('privacyPolicy.intro.body')} /></p>

            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mt-6 mb-3">{t('privacyPolicy.summary.heading')}</h3>
            <div className="bg-green-500/20 dark:bg-green-900/20 rounded-lg p-4 mb-4">
              <p className="text-slate-700 dark:text-slate-300 text-sm mb-2"><Rich text={t('privacyPolicy.summary.body')} /></p>
              <ul className="list-disc pl-6 text-slate-700 dark:text-slate-300 text-sm space-y-1">
                {t('privacyPolicy.summary.items', { returnObjects: true }).map((item) => <li key={item}>{item}</li>)}
              </ul>
            </div>

            {sections.map((key) => (
              <div key={key}>
                <h3 className="text-lg font-semibold text-slate-900 dark:text-white mt-6 mb-3">{t(`privacyPolicy.${key}.heading`)}</h3>
                <p className="text-slate-700 dark:text-slate-300 mb-4"><Rich text={t(`privacyPolicy.${key}.body`)} /></p>
              </div>
            ))}

            <h3 className="text-lg font-semibold text-slate-900 dark:text-white mt-6 mb-3">{t('privacyPolicy.contact.heading')}</h3>
            <p className="text-slate-700 dark:text-slate-300 mb-4">
              {t('privacyPolicy.contact.prompt')} <button onClick={() => { onClose(); openContactPopup(); }} className="text-sky-700 dark:text-sky-300 hover:underline">{t('contact.title')}</button>{t('privacyPolicy.contact.suffix')}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
