import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';
import ThemeToggle from './ThemeToggle';
import LanguageSwitcher from './LanguageSwitcher';
import { useLocalizedPath } from '../i18n/paths';
import monitorIconUrl from '../public/monitor_icon_40.png';
import monitorIconUrl2x from '../public/monitor_icon_64.png';

export default function Header({ theme, onToggleTheme }) {
  const { t } = useTranslation('edb');
  const localize = useLocalizedPath();
  const { pathname } = useLocation();
  const onGuides = /\/guides(?:\/|$)/.test(pathname);
  const onBlog = /\/blog(?:\/|$)/.test(pathname);

  return (
    <header className="site-header fixed top-0 left-0 right-0 z-50">
      <a className="skip-link" href="#main-content">{t('header.skipToContent', { defaultValue: 'Skip to content' })}</a>
      <div className="site-header-inner max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <a href={localize('/')} className="site-brand flex items-center gap-3" aria-label={t('header.appName')}>
            <img 
              src={monitorIconUrl} 
              srcSet={`${monitorIconUrl} 1x, ${monitorIconUrl2x} 2x`}
              alt={t('header.logoAlt')}
              className="site-brand-icon w-10 h-10"
              width={40}
              height={40}
              loading="eager"
              decoding="async"
              fetchPriority="high"
            />
            <span className="site-brand-name text-xl font-bold">
              {t('header.appName')}
            </span>
          </a>
          
          <nav className="site-nav hidden md:flex items-center" aria-label={t('header.primaryNavigation', { defaultValue: 'Primary navigation' })}>
            <a href={`${localize('/')}#how-it-works`} className="site-nav-link">
              {t('header.howItWorks')}
            </a>
            <a href={`${localize('/')}#features`} className="site-nav-link">
              {t('header.features')}
            </a>
            <a href={`${localize('/')}#faq`} className="site-nav-link">
              {t('header.faq')}
            </a>
            <a href={localize('/guides')} className="site-nav-link" aria-current={onGuides ? 'page' : undefined}>
              {t('header.guides')}
            </a>
            <a href={localize('/blog')} className="site-nav-link" aria-current={onBlog ? 'page' : undefined}>
              {t('header.blog')}
            </a>
          </nav>

          <div className="flex items-center gap-3">
            <LanguageSwitcher />
            <ThemeToggle theme={theme} onToggle={onToggleTheme} />
          </div>
        </div>
      </div>
    </header>
  );
}
